    setCelebrationEligible(false);
    setFirstScanCompleted(false);
    setCelebrating(true);
  }).catch(()=>{firstLibraryCelebrationClaimedRef.current=false;});
},[celebrationEligible,firstScanCompleted,onboardingDone,hasPublishedLocalWork,localScanning,
